package android.content.pm;public class PackageManager{public static final int MATCH_DEFAULT_ONLY=65536;public String browser="browser.default";public boolean queryThrows;public android.content.Intent probe;public ResolveInfo resolveActivity(android.content.Intent i,int flags){probe=i;if(queryThrows)throw new SecurityException();if(browser==null)return null;ResolveInfo r=new ResolveInfo();r.activityInfo=new ActivityInfo();r.activityInfo.packageName=browser;return r;}public static final String FEATURE_PICTURE_IN_PICTURE="android.software.picture_in_picture";public boolean pip=true;public boolean hasSystemFeature(String name){return pip;}public boolean installed=true;public int queries;public ApplicationInfo getApplicationInfo(String pkg,int flags)throws Exception{queries++;if(!installed)throw new Exception();return new ApplicationInfo();}public android.graphics.drawable.Drawable getApplicationIcon(String name)throws Exception{if(!installed)throw new Exception();return new android.graphics.drawable.Drawable();}}